"""Data-driven course directory. Course pages keep their own lessons and assets."""
import html
import json
from pathlib import Path

COURSES=json.loads((Path(__file__).resolve().parents[1]/'content/courses.json').read_text())
def entry(course,lang):return course['entry'][lang]
def render(lang):
    z=lambda value:value[lang]
    e=lambda value:html.escape(str(value),quote=True)
    cards=[]
    for course in COURSES:
        badge=z(['作者原站 ↗','Author-hosted ↗']) if course['external'] else z(['本站课程','On this site'])
        cards.append(f'''<article class="hub-course" data-hub-course="{e(course['id'])}"><div class="hub-card-top"><span class="eyebrow">{e(course['id']).upper()} / {course['units']} {z(['学习单元','UNITS'])}</span><span class="hub-badge">{badge}</span></div><h3><a href="{e(entry(course,lang))}">{e(course['title'])}</a></h3><p class="hub-course-subtitle">{e(z(course['subtitle']))}</p><p class="hub-course-description">{e(z(course['description']))}</p><div class="hub-tags">{''.join('<span>'+e(topic)+'</span>' for topic in course['topics'])}</div><p class="hub-course-prereq">{z(['先修','Prerequisites'])} · {e(z(course['prerequisites']))}</p><div class="hub-card-bottom"><span>{e(course['author'])} · 中文 / English</span><a class="btn primary" href="{e(entry(course,lang))}">{z(['进入课程','Open course'])} {'↗' if course['external'] else '→'}</a></div></article>''')
    cluster=next(c for c in COURSES if c['id']=='clustering')
    partition=next(c for c in COURSES if c['id']=='partitioning')
    total=sum(c['units'] for c in COURSES)
    return f'''<section class="wrap hub-hero"><div><p class="eyebrow">LEARNING EDA / INTERACTIVE OPEN COURSES</p><h1>{z(['从连接出发，<br>读懂芯片算法。','Follow the connections.<br>Understand the algorithms.'])}</h1><p class="lead">{z(['把概念变成可以观察、尝试和验证的过程。从聚类到划分，选择你的学习起点，在图上看见算法如何作出决定。','Turn concepts into something you can observe, try and verify. Choose a starting point, from clustering to partitioning, and see how algorithms make decisions.'])}</p><div class="btn-row"><a class="btn primary" href="courses/index.html">{z(['探索课程','Explore courses'])} ↓</a><a class="btn quiet" href="courses/index.html#map">{z(['我该从哪里开始','Find your starting point'])} →</a><button type="button" class="btn quiet" data-start-tour>{z(['新手引导','Getting started'])} ◎</button></div><p class="hub-continue"><a data-continue hidden></a></p><p class="byline">{len(COURSES)} {z(['门开放课程','open courses'])} · {total} {z(['个学习单元','learning units'])} · 中文 / English</p></div><figure class="hub-art" aria-label="{z(['从相互连接的节点，到聚类与划分两种学习视角','Connected vertices lead to two perspectives: clustering and partitioning'])}"><p class="eyebrow">ONE GRAPH / TWO PERSPECTIVES</p><svg viewBox="0 0 480 190" role="img" aria-label="{z(['五个相互连接的节点','Five connected vertices'])}"><path d="M65 85 180 42 245 135 365 50 420 140M65 85 245 135M180 42 365 50M245 135 420 140" fill="none" stroke="#618780" stroke-width="1.5"/><path d="M245 135 365 50" stroke="#ddbd78" stroke-width="2" stroke-dasharray="5 5"/><g fill="#13303a" stroke="#87c6b1" stroke-width="2"><circle cx="65" cy="85" r="16"/><circle cx="180" cy="42" r="20"/><circle cx="245" cy="135" r="24"/></g><g fill="#13303a" stroke="#8fb1e6" stroke-width="2"><circle cx="365" cy="50" r="20"/><circle cx="420" cy="140" r="16"/></g></svg><div class="hub-perspectives"><a href="{e(entry(cluster,lang))}"><small>01 / CLUSTERING</small><strong>{z(['哪些单元应该相聚？','What belongs together?'])}</strong><span>{z(['从关系出发，逐步聚合。','Build groups from connections.'])} ↗</span></a><a href="{e(entry(partition,lang))}"><small>02 / PARTITIONING</small><strong>{z(['怎样分组才能放得下？','How can every part fit?'])}</strong><span>{z(['明确代价，满足约束。','Measure costs. Respect constraints.'])} →</span></a></div><figcaption>{z(['解释 · 影片 · 交互实验 · Python 练习','Explanations · films · interactive labs · Python'])}</figcaption></figure></section>
<section class="section hub-directory" id="courses"><div class="wrap"><div class="section-head"><div><p class="eyebrow">01 / COURSE LIBRARY</p><h2>{z(['选择一门，开始探索','Choose a course. Start exploring.'])}</h2><a class="section-link" href="courses/index.html">{z(['完整目录与学习地图','Full directory and learning map'])} →</a></div><p>{z(['两种视角，共同理解芯片中的连接与分组。每门课保留自己的学习路线、实验和贡献记录。','Two perspectives on connections and groups in chip design. Each course has its own learning path, experiments and contributor credits.'])}</p></div><div class="hub-course-grid">{''.join(cards)}</div><p class="hub-external-note">{z(['Clustering 链接至 Su3037 的原课程网站；学习记录在各课程网站分别保存。','Clustering opens Su3037’s original course website. Each course website stores its learning records separately.'])}</p></div></section>
<section class="intro-band hub-path" id="learning-path"><div class="wrap"><div class="section-head"><div><p class="eyebrow">02 / FIND YOUR PATH</p><h2>{z(['从你的问题出发','Start with your question'])}</h2></div><p>{z(['两门课程可以独立学习，不要求先完成其中一门。按目标选择，再用实验检查理解。','The courses can be studied independently. Choose by your goal, then check your understanding through experiments.'])}</p></div><div class="hub-path-grid"><article><span class="eyebrow">01 / FOUNDATIONS</span><h3>{z(['刚接触 EDA 与图算法','New to EDA and graph algorithms'])}</h3><p>{z(['先认识节点、边权、割代价与面积，再选择课程。','Meet vertices, edge weights, cut cost and area before choosing a course.'])}</p><a href="foundations/index.html">{z(['打开基础速查','Open the foundations guide'])} →</a></article><article><span class="eyebrow">02 / CONNECTIONS</span><h3>{z(['想理解关系与合并','Explore relationships and merging'])}</h3><p>{z(['从亲和度和合并规则进入 Clustering，观察一个个簇如何形成。','Begin with affinity and merging rules in Clustering, and observe how groups form.'])}</p><a href="{e(entry(cluster,lang))}">{z(['进入 Clustering','Open Clustering'])} ↗</a></article><article><span class="eyebrow">03 / CONSTRAINTS</span><h3>{z(['想理解代价与约束','Explore costs and constraints'])}</h3><p>{z(['从 cut 与平衡进入 Partitioning，再研究 KL/FM 和多路划分。','Begin with cut and balance in Partitioning, then explore KL/FM and k-way methods.'])}</p><a href="{e(entry(partition,lang))}">{z(['进入 Partitioning','Open Partitioning'])} →</a></article></div></div></section>
<section class="section"><div class="wrap hub-next"><div><p class="eyebrow">03 / LEARN BY DOING</p><h2>{z(['先预测，再运行。','Predict first. Then run.'])}</h2><p>{z(['读解释、看影片，在实验中逐步运行，再用挑战和自己的代码验证。让每一步都有可以检查的理由。','Read, watch, step through experiments, then verify with challenges and your own code. Give every decision a reason you can inspect.'])}</p></div><div id="intro"><p class="eyebrow">PARTITIONING / 03:10</p><h3>{z(['先用三分钟建立直觉','Build intuition in three minutes'])}</h3><p>{z(['从分组的两难开始，认识割代价、平衡与课程中的方法。','Start with an assignment dilemma and meet cut cost, balance and the course methods.'])}</p><a class="section-link" href="{e(entry(partition,lang))}#intro">{z(['观看首页导论片','Watch the introduction'])} →</a></div></div></section><span id="curriculum" hidden></span>'''
